-- ----------------------------
-- Function structure for validate_prediction
-- ----------------------------
DROP FUNCTION IF EXISTS "public"."validate_prediction"("prediction_id" int4, "actual_numbers" _int4);
CREATE FUNCTION "public"."validate_prediction"("prediction_id" int4, "actual_numbers" _int4)
  RETURNS "pg_catalog"."int4" AS $BODY$
DECLARE
    pred RECORD;
    correct_count INTEGER;
BEGIN
    SELECT * INTO pred FROM predictions WHERE id = prediction_id;
    
    IF FOUND THEN
        -- Calculer le nombre de numéros corrects
        SELECT COUNT(*) INTO correct_count
        FROM unnest(pred.numeros) AS pred_num
        WHERE pred_num = ANY(actual_numbers);
        
        -- Mettre à jour la prédiction
        UPDATE predictions 
        SET correct_count = correct_count,
            is_validated = TRUE,
            updated_at = CURRENT_TIMESTAMP
        WHERE id = prediction_id;
        
        RETURN correct_count;
    END IF;
    
    RETURN 0;
END;
$BODY$
  LANGUAGE plpgsql VOLATILE
  COST 100;

